def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bikes = image_patch.find("bike")
    kids = image_patch.find("kid")

    if not bikes or not kids:
        return image_patch

    bike_centers = [(bike.left + bike.right) / 2 for bike in bikes]
    kid_centers = [(kid.left + kid.right) / 2 for kid in kids]

    between = []
    for i, bike_center in enumerate(bike_centers):
        for j, kid_center in enumerate(kid_centers):
            if abs(bike_center - kid_center) < min(abs(bike_centers[i] - bike_centers[j]) for j in range(len(bike_centers)) if i != j):
                between.append((i, j))

    if not between:
        return bikes[0]

    best_bike_idx, _ = min(between, key=lambda x: abs(bike_centers[x[0]] - kid_centers[x[1]]))
    return bikes[best_bike_idx]

